import { randomBytes } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import { dirname } from "node:path";

/**
 * A tiny book store backed by a single JSON file.
 *
 * The whole list is kept in memory and rewritten on every change. Writes go
 * to a temp file first and are then renamed over the real file, so a crash
 * mid-write never leaves a half-written books.json behind.
 */
export function createStore(filePath) {
  let books = null;
  let writing = Promise.resolve();

  async function load() {
    if (books) return books;
    try {
      const parsed = JSON.parse(await readFile(filePath, "utf8"));
      books = Array.isArray(parsed.books) ? parsed.books : [];
    } catch (err) {
      if (err.code !== "ENOENT") throw err;
      books = [];
    }
    return books;
  }

  function save() {
    // Chain writes so two quick changes can't interleave on disk.
    const snapshot = JSON.stringify({ books }, null, 2) + "\n";
    writing = writing
      .catch(() => {})
      .then(async () => {
        await mkdir(dirname(filePath), { recursive: true });
        const tmp = `${filePath}.${process.pid}.tmp`;
        await writeFile(tmp, snapshot);
        await rename(tmp, filePath);
      });
    return writing;
  }

  return {
    async list() {
      return [...(await load())];
    },

    async get(id) {
      return (await load()).find((b) => b.id === id) ?? null;
    },

    async add({ title, author, notes = "" }) {
      const all = await load();
      let id;
      do id = randomBytes(6).toString("base64url");
      while (all.some((b) => b.id === id));
      const book = {
        id,
        title,
        author,
        notes,
        status: "reading",
        addedAt: new Date().toISOString(),
        finishedAt: null,
      };
      all.push(book);
      await save();
      return book;
    },

    async markFinished(id) {
      const book = (await load()).find((b) => b.id === id);
      if (!book) return null;
      if (book.status !== "finished") {
        book.status = "finished";
        book.finishedAt = new Date().toISOString();
        await save();
      }
      return book;
    },
  };
}

