const escapeMap = {
  "&": "&amp;",
  "<": "&lt;",
  ">": "&gt;",
  '"': "&quot;",
  "'": "&#39;",
};

export function escape(value) {
  return String(value ?? "").replace(/[&<>"']/g, (c) => escapeMap[c]);
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 40rem; margin: 2rem auto; padding: 0 1rem; line-height: 1.5; color: #222; }
  h1 a { color: inherit; text-decoration: none; }
  ul { list-style: none; padding: 0; }
  li { display: flex; justify-content: space-between; align-items: center; gap: 1rem; padding: .5rem 0; border-bottom: 1px solid #eee; }
  li form { margin: 0; }
  .muted { color: #777; }
  .error { color: #b00020; }
  label { display: block; margin-top: .75rem; }
  input, textarea { width: 100%; box-sizing: border-box; padding: .4rem; font: inherit; }
  textarea { min-height: 6rem; }
  button { margin-top: .75rem; padding: .4rem .9rem; font: inherit; cursor: pointer; }
  li button { margin-top: 0; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: .75rem; border-radius: 4px; }
</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const finishButton =
    book.status === "reading"
      ? `<form method="post" action="/books/${escape(book.id)}/finish"><button type="submit">Mark finished</button></form>`
      : "";
  return `<li>
  <span><a href="/books/${escape(book.id)}">${escape(book.title)}</a> <span class="muted">by ${escape(book.author)}</span></span>
  ${finishButton}
</li>`;
}

function bookList(books, emptyText) {
  if (books.length === 0) return `<p class="muted">${escape(emptyText)}</p>`;
  return `<ul>\n${books.map(bookItem).join("\n")}\n</ul>`;
}

export function homePage(books, { error = "", values = {} } = {}) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt ?? "").localeCompare(a.finishedAt ?? ""));

  return layout(
    "My books",
    `<h2>Currently reading</h2>
${bookList(reading, "Nothing on the go right now.")}

<h2>Finished</h2>
${bookList(finished, "No finished books yet.")}

<h2>Add a book</h2>
${error ? `<p class="error">${escape(error)}</p>` : ""}
<form method="post" action="/books">
  <label>Title <input name="title" required value="${escape(values.title)}"></label>
  <label>Author <input name="author" required value="${escape(values.author)}"></label>
  <label>Notes <textarea name="notes">${escape(values.notes)}</textarea></label>
  <button type="submit">Add book</button>
</form>`,
  );
}

export function bookPage(book) {
  const status =
    book.status === "finished"
      ? `Finished${book.finishedAt ? ` on ${escape(book.finishedAt.slice(0, 10))}` : ""}`
      : "Currently reading";
  const finishButton =
    book.status === "reading"
      ? `<form method="post" action="/books/${escape(book.id)}/finish"><button type="submit">Mark finished</button></form>`
      : "";

  return layout(
    book.title,
    `<h2>${escape(book.title)}</h2>
<p>by ${escape(book.author)}</p>
<p class="muted">${status}</p>
<h3>Notes</h3>
${book.notes ? `<div class="notes">${escape(book.notes)}</div>` : `<p class="muted">No notes.</p>`}
${finishButton}
<p><a href="/">&larr; All books</a></p>`,
  );
}

export function notFoundPage() {
  return layout(
    "Not found",
    `<p>That book doesn't exist (or the link is wrong).</p>
<p><a href="/">&larr; All books</a></p>`,
  );
}

