  button { margin-top: .75rem; padding: .4rem .9rem; font: inherit; cursor: pointer; }
  li button { margin-top: 0; }
  .notes { white-space: pre-wrap; background: #f7f7f7; padding: .75rem; border-radius: 4px; }
</style>
</head>
<body>
<h1><a href="/">My books</a></h1>
${body}
</body>
</html>`;
}

function bookItem(book) {
  const finishButton =
    book.status === "reading"
      ? `<form method="post" action="/books/${escape(book.id)}/finish"><button type="submit">Mark finished</button></form>`
      : "";
  return `<li>
  <span><a href="/books/${escape(book.id)}">${escape(book.title)}</a> <span class="muted">by ${escape(book.author)}</span></span>
  ${finishButton}
</li>`;
}

function bookList(books, emptyText) {
  if (books.length === 0) return `<p class="muted">${escape(emptyText)}</p>`;
  return `<ul>\n${books.map(bookItem).join("\n")}\n</ul>`;
}

export function homePage(books, { error = "", values = {} } = {}) {
  const reading = books.filter((b) => b.status === "reading");
  const finished = books
    .filter((b) => b.status === "finished")
    .sort((a, b) => (b.finishedAt ?? "").localeCompare(a.finishedAt ?? ""));

  return layout(
    "My books",
    `<h2>Currently reading</h2>
${bookList(reading, "Nothing on the go right now.")}

<h2>Finished</h2>
${bookList(finished, "No finished books yet.")}

<h2>Add a book</h2>
${error ? `<p class="error">${escape(error)}</p>` : ""}
<form method="post" action="/books">
  <label>Title <input name="title" required value="${escape(values.title)}"></label>
  <label>Author <input name="author" required value="${escape(values.author)}"></label>
  <label>Notes <textarea name="notes">${escape(values.notes)}</textarea></label>
  <button type="submit">Add book</button>
</form>`,
  );
}

export function bookPage(book) {
  const status =
    book.status === "finished"
      ? `Finished${book.finishedAt ? ` on ${escape(book.finishedAt.slice(0, 10))}` : ""}`
      : "Currently reading";
  const finishButton =
    book.status === "reading"
      ? `<form method="post" action="/books/${escape(book.id)}/finish"><button type="submit">Mark finished</button></form>`
      : "";

  return layout(
    book.title,
    `<h2>${escape(book.title)}</h2>
<p>by ${escape(book.author)}</p>
<p class="muted">${status}</p>
<h3>Notes</h3>
${book.notes ? `<div class="notes">${escape(book.notes)}</div>` : `<p class="muted">No notes.</p>`}
${finishButton}
<p><a href="/">&larr; All books</a></p>`,
  );
}

export function notFoundPage() {
  return layout(
    "Not found",
    `<p>That book doesn't exist (or the link is wrong).</p>
<p><a href="/">&larr; All books</a></p>`,
  );
}

import { bookPage, homePage, notFoundPage } from "./views.js";

const MAX_BODY_BYTES = 64 * 1024;
const LIMITS = { title: 300, author: 300, notes: 20000 };

function send(res, status, html) {
  res.writeHead(status, { "Content-Type": "text/html; charset=utf-8" });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { Location: location });
  res.end();
}

function readForm(req) {
  return new Promise((resolve, reject) => {
    let size = 0;
    const chunks = [];
    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        reject(Object.assign(new Error("Body too large"), { status: 413 }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => resolve(new URLSearchParams(Buffer.concat(chunks).toString("utf8"))));
    req.on("error", reject);
  });
}

/** Returns a (req, res) handler for node:http. */
export function createApp(store) {
  async function handle(req, res) {
    const { pathname } = new URL(req.url, "http://localhost");
    const method = req.method;

    if (pathname === "/" && (method === "GET" || method === "HEAD")) {
      return send(res, 200, homePage(await store.list()));
    }

    if (pathname === "/books" && method === "POST") {
      const form = await readForm(req);
      const values = {
        title: (form.get("title") ?? "").trim(),
        author: (form.get("author") ?? "").trim(),
        notes: (form.get("notes") ?? "").trim(),
      };
      let error = "";
      if (!values.title || !values.author) error = "Please enter both a title and an author.";
      for (const [field, max] of Object.entries(LIMITS)) {
        if (values[field].length > max) error = `The ${field} is too long (max ${max} characters).`;
      }
      if (error) return send(res, 400, homePage(await store.list(), { error, values }));

      const book = await store.add(values);
      return redirect(res, `/books/${book.id}`);
    }

    const finishMatch = pathname.match(/^\/books\/([\w-]+)\/finish$/);
    if (finishMatch && method === "POST") {
      const book = await store.markFinished(finishMatch[1]);
      if (!book) return send(res, 404, notFoundPage());
      // Go back to wherever the button was pressed (home or the book page).
      const back = req.headers.referer ? new URL(req.headers.referer, "http://localhost").pathname : "/";
      return redirect(res, back === `/books/${book.id}` ? back : "/");
    }

    const bookMatch = pathname.match(/^\/books\/([\w-]+)$/);
    if (bookMatch && (method === "GET" || method === "HEAD")) {
      const book = await store.get(bookMatch[1]);
      if (!book) return send(res, 404, notFoundPage());
      return send(res, 200, bookPage(book));
    }

    return send(res, 404, notFoundPage());
  }

  return (req, res) => {
    handle(req, res).catch((err) => {
      if (!err.status) console.error(err);
      if (!res.headersSent) {
        res.writeHead(err.status ?? 500, { "Content-Type": "text/plain; charset=utf-8" });
      }
      res.end(err.status === 413 ? "Too much data." : "Something went wrong.");
    });
  };
}

import { createServer } from "node:http";
import { resolve } from "node:path";
import { createApp } from "./src/app.js";
import { createStore } from "./src/store.js";

const port = Number(process.env.PORT ?? 3000);
const host = process.env.HOST ?? "127.0.0.1";
const dataFile = resolve(process.env.DATA_FILE ?? "data/books.json");

const server = createServer(createApp(createStore(dataFile)));
server.listen(port, host, () => {
  console.log(`Book tracker running at http://${host === "0.0.0.0" ? "localhost" : host}:${port}`);
  console.log(`Saving books to ${dataFile}`);
});

