import { createServer } from "node:http";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createApp } from "../src/app.js";
import { createStore } from "../src/store.js";

let dir, dataFile, server, base;

async function start() {
  server = createServer(createApp(createStore(dataFile)));
  await new Promise((r) => server.listen(0, "127.0.0.1", r));
  base = `http://127.0.0.1:${server.address().port}`;
}

async function stop() {
  await new Promise((r) => server.close(r));
}

function post(path, fields = {}, headers = {}) {
  return fetch(base + path, {
    method: "POST",
    body: new URLSearchParams(fields),
    redirect: "manual",
    headers,
  });
}

async function addBook(fields) {
  const res = await post("/books", fields);
  expect(res.status).toBe(303);
  return res.headers.get("location");
}

beforeEach(async () => {
  dir = await mkdtemp(join(tmpdir(), "books-"));
  dataFile = join(dir, "data", "books.json");
  await start();
});

afterEach(async () => {
  await stop();
  await rm(dir, { recursive: true, force: true });
});

describe("book tracker", () => {
  it("shows empty lists and the add form on a fresh start", async () => {
    const html = await (await fetch(base + "/")).text();
    expect(html).toContain("Currently reading");
    expect(html).toContain("Nothing on the go right now.");
    expect(html).toContain("No finished books yet.");
    expect(html).toContain('<form method="post" action="/books">');
  });

  it("adds a book, lists it as reading, and shows its own page", async () => {
    const link = await addBook({ title: "Dune", author: "Frank Herbert", notes: "Spice.\nSand." });
    expect(link).toMatch(/^\/books\/[\w-]+$/);

    const page = await fetch(base + link);
    expect(page.status).toBe(200);
    const html = await page.text();
    expect(html).toContain("<h2>Dune</h2>");
    expect(html).toContain("by Frank Herbert");
    expect(html).toContain("Spice.\nSand.");
    expect(html).toContain("Currently reading");

    const home = await (await fetch(base + "/")).text();
    const readingSection = home.split("<h2>Finished</h2>")[0];
    expect(readingSection).toContain(`href="${link}"`);
  });

  it("marks a book finished and moves it to the finished list", async () => {
    const link = await addBook({ title: "Emma", author: "Jane Austen" });
    const res = await post(`${link}/finish`);
    expect(res.status).toBe(303);
    expect(res.headers.get("location")).toBe("/");

    const home = await (await fetch(base + "/")).text();
    const [reading, finished] = home.split("<h2>Finished</h2>");
    expect(reading).not.toContain("Emma");
    expect(finished).toContain("Emma");

    const page = await (await fetch(base + link)).text();
    expect(page).toMatch(/Finished on \d{4}-\d{2}-\d{2}/);
    expect(page).not.toContain("Mark finished");
  });

  it("returns to the book page when finishing from there", async () => {
    const link = await addBook({ title: "Emma", author: "Jane Austen" });
    const res = await post(`${link}/finish`, {}, { Referer: base + link });
    expect(res.headers.get("location")).toBe(link);
  });

  it("keeps books after a restart", async () => {
    const link = await addBook({ title: "Middlemarch", author: "George Eliot", notes: "Long." });
    await post(`${link}/finish`);
    await stop();
    await start();

    const html = await (await fetch(base + link)).text();
    expect(html).toContain("Middlemarch");
    expect(html).toContain("Long.");
    expect(html).toContain("Finished on");

    const saved = JSON.parse(await readFile(dataFile, "utf8"));
    expect(saved.books).toHaveLength(1);
    expect(saved.books[0]).toMatchObject({ title: "Middlemarch", status: "finished" });
  });

  it("rejects a book without title or author and keeps what was typed", async () => {
    const res = await post("/books", { title: "Only a title", notes: "hi" });
    expect(res.status).toBe(400);
    const html = await res.text();
    expect(html).toContain("Please enter both a title and an author.");
    expect(html).toContain('value="Only a title"');
    expect((await (await fetch(base + "/")).text())).toContain("Nothing on the go right now.");
  });

  it("escapes HTML in user input", async () => {
    const link = await addBook({ title: "<script>alert(1)</script>", author: "A & B" });
    const html = await (await fetch(base + link)).text();
    expect(html).not.toContain("<script>alert(1)</script>");
    expect(html).toContain("&lt;script&gt;");
    expect(html).toContain("A &amp; B");
  });

  it("shows a 404 page for unknown books", async () => {
    expect((await fetch(base + "/books/nope")).status).toBe(404);
    expect((await post("/books/nope/finish")).status).toBe(404);
  });
});

